import React from 'react';
import './Page.css';

const Terms = () => {
  return (
    <main className="page">
      <div className="page-inner">
        <header className="page-hero">
          <h1>Terms &amp; Conditions</h1>
          <p className="muted">Please read these terms carefully before using our service.</p>
        </header>

        <section className="page-card">
          <h3>Use of Service</h3>
          <p className="muted">You agree to use the service only for lawful purposes and in a way that does not infringe the rights of others or restrict their use and enjoyment of the service.</p>

          <h3 style={{ marginTop: '1rem' }}>Limitation of Liability</h3>
          <p className="muted">To the fullest extent permitted by law, Ravindra Stores will not be liable for any indirect or consequential loss arising from your use of the service.</p>
        </section>
      </div>
    </main>
  );
};

export default Terms;
